package com.zerostreams.app;
import android.content.*;import android.os.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Persistent, single-worker direct-video queue; URLs and API keys are never persisted. */
final class DirectDownloads {
 interface Resolver{String resolve(JSONObject job)throws Exception;}interface ConnectionOpener{HttpURLConnection open(String url,long offset,String validator)throws Exception;}final Resolver resolver;final ConnectionOpener opener;static DirectDownloads instance;static synchronized DirectDownloads get(Context c){if(instance==null)instance=new DirectDownloads(c.getApplicationContext());return instance;}final Context context;final File index,folder;final List<JSONObject> jobs=new ArrayList<>();final ExecutorService worker=Executors.newSingleThreadExecutor();volatile JSONObject active;volatile HttpURLConnection connection;volatile boolean running;long updated;Runnable listener;
 private DirectDownloads(Context c){this(c,null,null,null);}DirectDownloads(Context c,File root,Resolver source,ConnectionOpener fetcher){context=c;resolver=source;opener=fetcher;index=new File(root==null?c.getFilesDir():root,"direct-downloads.json");File base=root==null?c.getExternalFilesDir(Environment.DIRECTORY_MOVIES):root;folder=new File(base==null?c.getFilesDir():base,"ZeroPlay");folder.mkdirs();try{JSONArray rows=new JSONArray(Catalog.read(new FileInputStream(index),2_000_000));for(int i=0;i<rows.length();i++){JSONObject j=rows.getJSONObject(i);if(Arrays.asList("downloading","preparing").contains(state(j)))j.put("state","queued");jobs.add(j);}}catch(Exception ignored){}check();}
 synchronized void save(){try{File temp=new File(index+".tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(new JSONArray(jobs).toString().getBytes("UTF-8"));out.getFD().sync();}if(!temp.renameTo(index))throw new IOException();}catch(Exception error){for(JSONObject j:jobs)if(Arrays.asList("queued","preparing","downloading").contains(state(j))){set(j,"state","paused");set(j,"error","Cannot save download history. Free storage and check permissions, then resume.");}if(connection!=null)connection.disconnect();}}
 synchronized void check(){for(JSONObject j:jobs)if(state(j).equals("completed")&&!new File(j.optString("file")).isFile())set(j,"state","missing");}
 synchronized JSONArray list(){check();try{return new JSONArray(new JSONArray(jobs).toString());}catch(JSONException ignored){return new JSONArray();}}
 synchronized String state(JSONObject j){return j.optString("state");}
 synchronized void set(JSONObject j,String name,Object value){try{j.put(name,value);}catch(Exception ignored){}}
 synchronized void update(boolean persist){if(persist)save();if(listener!=null)new Handler(Looper.getMainLooper()).post(listener);}
 static String filename(String title,String year,String type,int season,int episode,String episodeTitle){String name=type.equals("tv")?title+String.format(Locale.ROOT," - S%02dE%02d",season,episode)+(episodeTitle.isEmpty()?"":" - "+episodeTitle):title+(year.matches("[0-9]{4}")?" ("+year+")":"");name=name.replaceAll("[<>:\"/\\\\|?*\\x00-\\x1f]","_").replaceAll("[. ]+$","");if(name.length()>180)name=name.substring(0,180);if(name.isEmpty()||name.matches("(?i)^(CON|PRN|AUX|NUL|COM[0-9]|LPT[0-9])(\\..*)?$"))name="ZeroPlay - "+name;return name+".mp4";}
 synchronized String add(String type,String id,String title,String year,String poster,int season,int episode,String episodeTitle)throws Exception{String identity=type+"-"+id+(type.equals("tv")?"-"+season+"-"+episode:"");check();for(JSONObject j:jobs)if(j.optString("id").equals(identity)){if(Arrays.asList("failed","cancelled","missing").contains(state(j)))action(identity,"resume");return identity;}File file=new File(folder,filename(title,year,type,season,episode,episodeTitle));boolean conflict=file.exists();String stem=file.getName().replaceAll("\\.[^.]+$","");File[] stored=folder.listFiles();if(stored!=null)for(File entry:stored)if(entry.getName().replaceAll("\\.(mp4|mov|mkv|webm|ts|mpg|flv|avi)(\\.part)?$","").equals(stem))conflict=true;for(JSONObject entry:jobs)if(new File(entry.optString("file")).getName().replaceAll("\\.[^.]+$","").equals(stem))conflict=true;if(conflict)file=new File(folder,identity+" - "+file.getName());JSONObject j=new JSONObject().put("id",identity).put("tmdb",id).put("type",type).put("title",title).put("poster",poster).put("season",season).put("episode",episode).put("episodeTitle",episodeTitle).put("file",file.toString()).put("bytes",0).put("total",0).put("speed",0).put("state","queued");jobs.add(j);update(true);start();return identity;}
 synchronized boolean hasWork(){if(running)return true;for(JSONObject j:jobs)if(state(j).equals("queued"))return true;return false;}
 synchronized void pauseAll(){for(JSONObject j:jobs)if(java.util.Arrays.asList("queued","preparing","downloading").contains(state(j))){set(j,"state","paused");set(j,"error","Android background download limit reached. Resume from Downloads.");}if(connection!=null)connection.disconnect();update(true);}
 void start(){if(resolver!=null){pump();return;}Intent intent=new Intent(context,RawCastDownloadService.class);if(Build.VERSION.SDK_INT>=26)context.startForegroundService(intent);else context.startService(intent);}
 synchronized void pump(){if(running)return;JSONObject next=null;for(JSONObject j:jobs)if(state(j).equals("queued")){next=j;break;}if(next==null)return;running=true;active=next;JSONObject job=next;worker.execute(()->{run(job);synchronized(this){running=false;active=null;update(true);pump();}});}
 synchronized void action(String id,String action)throws Exception{JSONObject j=null;for(JSONObject row:jobs)if(row.optString("id").equals(id)){j=row;break;}if(j==null)throw new IOException("Download no longer exists.");File file=new File(j.optString("file"));if(action.equals("delete")){if(!Arrays.asList("completed","missing").contains(state(j)))throw new IOException("Only completed videos can be deleted.");if(file.exists()&&!file.delete())throw new IOException("Could not delete video. Check permissions.");jobs.remove(j);}else if(action.equals("history")){if(j==active||Arrays.asList("queued","downloading","preparing").contains(state(j)))throw new IOException("Pause or cancel first.");jobs.remove(j);}else if(action.equals("pause")||action.equals("cancel")){set(j,"state",action.equals("pause")?"paused":"cancelled");if(j==active&&connection!=null)connection.disconnect();else if(action.equals("cancel"))new File(file+".part").delete();}else if(action.equals("resume")||action.equals("retry")){if(j==active)return;set(j,"state","queued");set(j,"error","");start();}else throw new IOException("Unsupported action.");update(true);pump();}
 void run(JSONObject j){File file=new File(j.optString("file")),part=new File(file+".part");for(int attempt=0;attempt<4;attempt++){if(Arrays.asList("paused","cancelled").contains(state(j)))return;try{set(j,"state","preparing");update(true);String url=resolver!=null?resolver.resolve(j):RawCast.get(context).resolve(j.optString("type"),j.optString("tmdb"),j.optInt("season"),j.optInt("episode"),j.optBoolean("resolved")).getString("url");if(!state(j).equals("preparing"))return;set(j,"resolved",true);long offset=part.exists()?part.length():0;if(offset<12)offset=0;HttpURLConnection c=opener!=null?opener.open(url,offset,j.optString("validator")):open(url,offset,j.optString("validator"));connection=c;int code=c.getResponseCode();if(code!=200&&code!=206)throw new IOException("Download server unavailable.");String type=c.getContentType();if(type!=null&&(type.startsWith("text/")||type.contains("json")||type.contains("mpegurl")))throw new IOException("Server did not return a direct video file.");long total=0;if(code==206){String range=c.getHeaderField("Content-Range");if(range==null||!range.startsWith("bytes "+offset+"-"))throw new IOException("Invalid resume response.");total=Long.parseLong(range.substring(range.indexOf('/')+1));}else{offset=0;String length=c.getHeaderField("Content-Length");total=length==null?0:Long.parseLong(length);}set(j,"validator",c.getHeaderField("ETag")!=null?c.getHeaderField("ETag"):c.getHeaderField("Last-Modified"));set(j,"total",total);set(j,"bytes",offset);set(j,"state","downloading");update(true);long bytes=offset,last=System.currentTimeMillis(),previous=bytes;try(InputStream input=c.getInputStream();FileOutputStream output=new FileOutputStream(part,offset>0)){byte[] buffer=new byte[128*1024];if(offset==0){byte[] header=new byte[12];int got=0;while(got<12){int amount=input.read(header,got,12-got);if(amount<0)throw new IOException("Server did not return a supported video file.");got+=amount;}if(MediaFiles.identify(header)==null)throw new IOException("Server did not return a supported video file.");output.write(header);bytes+=12;}int count;while((count=input.read(buffer))!=-1){if(!state(j).equals("downloading"))return;output.write(buffer,0,count);bytes+=count;set(j,"bytes",bytes);long now=System.currentTimeMillis();if(now-last>=800){set(j,"speed",(bytes-previous)*1000/(now-last));previous=bytes;last=now;update(false);}}output.getFD().sync();}if(!state(j).equals("downloading"))return;if(total>0&&bytes!=total)throw new IOException("Connection interrupted.");byte[] header=new byte[256];try(FileInputStream probe=new FileInputStream(part)){if(probe.read(header)<12)throw new IOException("Server returned an empty video file.");}String format=MediaFiles.identify(header);if(format==null)throw new IOException("Server did not return a supported video file.");set(j,"state","preparing");set(j,"speed",0);update(true);if(resolver==null&&!MediaFiles.playable(context,part,format))throw new IOException("Server returned a video codec unsupported by ZeroPlay on this device.");if(!state(j).equals("preparing"))return;File target=new File(file.toString().replaceAll("\\.(mp4|mov|mkv|webm|ts|mpg|flv|avi)$","."+format));if(target.exists()||!part.renameTo(target))throw new IOException("Could not finalize video file.");set(j,"file",target.toString());set(j,"format",format);set(j,"mime",MediaFiles.mime(format));set(j,"state","completed");set(j,"total",bytes);set(j,"error","");return;}catch(Exception error){if(Arrays.asList("paused","cancelled").contains(state(j)))return;String message=error.getMessage()==null?"Download interrupted.":error.getMessage();if(message.contains("ENOSPC")||folder.getUsableSpace()<1024*1024){set(j,"state","failed");set(j,"error","Storage is full. Free space and retry.");return;}if(attempt<3&&!message.startsWith("RawCast")&&!message.startsWith("Unavailable")&&!message.startsWith("Server")&&!message.startsWith("Invalid")){set(j,"state","preparing");set(j,"error","Connection interrupted; retrying.");try{Thread.sleep(1000L<<attempt);}catch(InterruptedException ignored){}continue;}set(j,"state","failed");set(j,"error",message.startsWith("RawCast")||message.startsWith("Unavailable")||message.startsWith("Server")?message:"Download failed. Check connection and storage, then retry.");return;}finally{if(connection!=null){connection.disconnect();connection=null;}set(j,"speed",0);if(state(j).equals("cancelled")){part.delete();set(j,"bytes",0);}}}}
 HttpURLConnection open(String address,long offset,String validator)throws Exception{for(int i=0;i<6;i++){URL url=new URL(address);if(!url.getProtocol().equals("https"))throw new IOException("Unsupported download URL.");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);if(offset>0){c.setRequestProperty("Range","bytes="+offset+"-");if(!validator.isEmpty())c.setRequestProperty("If-Range",validator);}int status=c.getResponseCode();if(status>=300&&status<400){String next=c.getHeaderField("Location");c.disconnect();address=new URL(url,next).toString();continue;}return c;}throw new IOException("Too many download redirects.");}
}
